package dev.zomboidmelee.boxing;
import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;
/** Viewmodel-only stance. Third-person shoulders/elbows remain the v23 implementation. */
public final class First24{
 public record Frame(double x,double y,double z,double pitch,double yaw,double roll,double wrist){}
 static final ModelPart[][][] FOREARM=new ModelPart[2][2][2],FIST=new ModelPart[2][2][2];
 static{for(int side=0;side<2;side++)for(int sleeve=0;sleeve<2;sleeve++)for(int slim=0;slim<2;slim++){int u=side==0?40:sleeve==0?32:48,v=side==0?(sleeve==0?22:38):54;float x=side==0?(slim==1?-2:-3):-1,w=slim==1?3:4;MeshDefinition mesh=new MeshDefinition();PartDefinition root=mesh.getRoot();CubeDeformation inflate=new CubeDeformation(sleeve==1?.25f:0);root.addOrReplaceChild("arm",CubeListBuilder.create().texOffs(u,v).addBox(x,0,-2,w,4,4,inflate),PartPose.ZERO);root.addOrReplaceChild("fist",CubeListBuilder.create().texOffs(u,v+4).addBox(x,0,-2,w,2,4,inflate),PartPose.ZERO);ModelPart m=LayerDefinition.create(mesh,64,64).bakeRoot();FOREARM[side][sleeve][slim]=m.getChild("arm");FIST[side][sleeve][slim]=m.getChild("fist");}}
 public static Frame frame(int kind,int side,int combo,double phase){int sign=side==0?1:-1;boolean active=side==Math.floorMod(combo,2);double a=Motion20.strike(kind,phase),hit=Math.max(0,a),load=Math.max(0,-a);double x=.28,y=-.50,z=-.32,pitch=-145,yaw=10,roll=7,wrist=0;
 if(kind==Motion20.LIGHT||kind==Motion20.HEAVY){if(active){if(kind==Motion20.LIGHT){x-=.22*hit-.045*load;y+=.27*hit-.025*load;z-=.22*hit-.04*load;pitch+=55*hit-6*load;yaw-=8*hit;roll+=4*hit;wrist=55*hit;}else{x+=.11*load-.36*hit;y+=.24*hit-.05*load;z+=.08*load-.16*hit;pitch+=48*hit-8*load;yaw+=15*load-36*hit;roll+=23*hit;wrist=65*hit;}}else{y+=.035*hit;z+=.015*hit;pitch-=4*hit;}}
 else if(kind==Motion20.SHOVE){x-=.08*hit;y+=.23*hit;z-=.25*hit;pitch+=55*hit;}
 else if(kind==Motion20.INTERACT||kind==Motion20.SEARCH){double reach=kind==Motion20.SEARCH?(1+Math.sin(phase*Math.PI*2+side*Math.PI))*.35:side==0?Motion20.track(phase,new double[]{0,.17,.39,.58,1},new double[]{0,.2,1,.82,0}):0;x-=.12*reach;y+=.20*reach;z-=.20*reach;pitch+=52*reach;wrist=25*reach;}
 else if(kind==Motion20.STOMP){double lift=StompMotion21.lift(phase);y-=.12*lift;x+=.035*lift;}
 return new Frame(sign*x,y,z,pitch,sign*yaw,sign*roll,sign*wrist);}
 static void mesh(PoseStack p,Object consumer,int light,int side,int layer,int slim,double wrist){p.pushPose();try{p.translate(0,-6/16d,0);p.scale(1,2.5f,1);Arms23.segment(FOREARM[side][layer][slim],p,consumer,light,655360,-1);}finally{p.popPose();}p.pushPose();try{double center=(side==0?-1:1)*(slim==1?.5:1)/16d;p.translate(center,4/16d,0);p.mulPose(Axis.YP.rotationDegrees((float)wrist));p.translate(-center,0,0);Arms23.segment(FIST[side][layer][slim],p,consumer,light,655360,-1);}finally{p.popPose();}}
 public static void draw(Object stack,Object buffers,int light,Object player,int side,int kind,int combo,double phase){Frame f=MoveClient25.first(player,side);if(f==null)f=Run29.frame(frame(kind,side,combo,phase),player,side,phase);drawFrame((PoseStack)stack,buffers,light,player,side,View30.pose(f,player,side,kind,phase));}
 public static void drawFrame(PoseStack p,Object buffers,int light,Object player,int side,Frame f){Object consumer=R.call(buffers,"getBuffer",R.call(R.type("net.minecraft.client.renderer.RenderType"),"entityCutoutNoCull",R.call(R.call(player,"getSkin"),"texture")));int slim=Arms23.slim(player)?1:0;p.pushPose();try{p.translate(f.x,f.y,f.z);p.scale(.82f,-.82f,.82f);p.mulPose(Axis.YP.rotationDegrees((float)f.yaw));p.mulPose(Axis.ZP.rotationDegrees((float)f.roll));p.mulPose(Axis.XP.rotationDegrees((float)f.pitch));mesh(p,consumer,light,side,0,slim,f.wrist);if(R.yes(R.call(player,"isModelPartShown",R.get(R.type("net.minecraft.world.entity.player.PlayerModelPart"),side==0?"RIGHT_SLEEVE":"LEFT_SLEEVE"))))mesh(p,consumer,light,side,1,slim,f.wrist);}finally{p.popPose();}}
}
